import * as THREE from './vendor/three.module.js';
const UP=new THREE.Vector3(0,1,0);
export const KAGE_SMOKE_DEFAULTS=Object.freeze({key:'v',projectileFuseSeconds:1.5,radius:8,duration:8,cooldown:12,maxActive:1,growSeconds:.35,fadeSeconds:.7,groundTolerance:.3,puffs:18,aiInterval:.35});
// Stationary smoke volumes; protection is queried at damage time, never stored on allies.
export class KageSmoke {
 constructor(scene,config,{ground,canDeploy=()=>true,onDeploy=()=>{}}){this.config={...KAGE_SMOKE_DEFAULTS,...config};Object.assign(this,{ground,canDeploy,onDeploy});this.root=new THREE.Group();this.root.name='Kage protective smoke';scene.add(this.root);const n=32,data=new Uint8Array(n*n*4);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const i=(y*n+x)*4,a=Math.max(0,1-Math.hypot((x-n/2)/(n/2),(y-n/2)/(n/2)));data[i]=data[i+1]=data[i+2]=255;data[i+3]=Math.round(Math.pow(a,1.6)*255);}this.texture=new THREE.DataTexture(data,n,n);this.texture.needsUpdate=true;this.shellGeometry=new THREE.SphereGeometry(1,32,16,0,Math.PI*2,0,Math.PI/2);this.ringGeometry=new THREE.RingGeometry(.985,1,64);this.canisterGeometry=new THREE.CylinderGeometry(.16,.19,.34,8);this.reset();}
 reset(){for(const d of this.domes||[])this.remove(d);this.domes=[];this.cooldown=0;this.deployed=0;this.blocked=0;this.time=0;this.aiClock=0;}
 deploy(origin,{reserved=false}={}){const c=this.config;if(!this.canDeploy()||!reserved&&this.cooldown>0||this.domes.length>=c.maxActive)return false;const center=this.ground(origin);if(!center)return false;const root=new THREE.Group();root.position.copy(center);this.root.add(root);const material=new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.DoubleSide,toneMapped:false,uniforms:{time:{value:0},fade:{value:1},flash:{value:0}},vertexShader:'varying vec3 p;varying vec3 viewDir;void main(){p=position;vec4 world=modelMatrix*vec4(position,1.);viewDir=cameraPosition-world.xyz;gl_Position=projectionMatrix*viewMatrix*world;}',fragmentShader:'varying vec3 p;varying vec3 viewDir;uniform float time;uniform float fade;uniform float flash;void main(){float a=sin(p.x*19.+time*.8)*sin(p.z*17.-time*.6)+sin(p.y*24.+p.x*11.+time);float mist=.5+.22*a;float rim=pow(1.-abs(dot(normalize(p),normalize(viewDir))),2.);gl_FragColor=vec4(mix(vec3(.39,.43,.49),vec3(.62,.65,.72),mist*.5+flash*.25),(.08+mist*.24+rim*.04)*fade);}'});
 const shell=new THREE.Mesh(this.shellGeometry,material);shell.scale.setScalar(c.radius);root.add(shell);const ring=new THREE.Mesh(this.ringGeometry,new THREE.MeshBasicMaterial({color:'#c6b6ed',transparent:true,opacity:.65,side:THREE.DoubleSide,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.position.y=.035;ring.scale.setScalar(c.radius);root.add(ring);const canister=new THREE.Mesh(this.canisterGeometry,new THREE.MeshStandardMaterial({color:'#333846',metalness:.65,roughness:.4,emissive:'#8d6baa',emissiveIntensity:.5}));canister.position.y=.2;root.add(canister);const puffs=[];for(let i=0;i<c.puffs;i++){const puff=new THREE.Sprite(new THREE.SpriteMaterial({map:this.texture,color:i%2?'#a6a8b6':'#777f91',transparent:true,opacity:.3,depthWrite:false}));root.add(puff);puffs.push(puff);}const dome={root,center:center.clone(),age:0,flash:0,shell,ring,puffs,material};this.domes.push(dome);if(!reserved)this.cooldown=c.cooldown;this.deployed++;this.animate(dome);this.onDeploy(center);return true;}
 contains(position){const c=this.config;return this.domes.some(d=>d.age<c.duration&&position.y>=d.center.y-c.groundTolerance&&(position.x-d.center.x)**2+(position.y-d.center.y)**2+(position.z-d.center.z)**2<=c.radius*c.radius);}
 protectsHero(hero){return !!this.domes.length&&!!hero?.root&&hero.enabled!==false&&this.contains(hero.root.getWorldPosition(new THREE.Vector3()).addScaledVector(hero.bodyUp||UP,1));}
 protectsUnit(unit){if(!this.domes.length||!unit||unit.kind==='robot'||unit.alive===false)return false;if(unit.kind==='hero')return this.protectsHero(unit.entity);const root=unit.entity?.root,point=root?root.getWorldPosition(new THREE.Vector3()).addScaledVector(UP,unit.kind==='bus'?1.5:1):unit.shapes?.[0]?.center;return !!point&&this.contains(point);}
 absorb(){this.blocked++;for(const d of this.domes)d.flash=.18;}
 animate(d){const c=this.config,fade=Math.min(1,(c.duration-d.age)/c.fadeSeconds),grow=Math.min(1,.25+d.age/c.growSeconds);d.material.uniforms.time.value=d.age;d.material.uniforms.fade.value=Math.max(0,fade);d.material.uniforms.flash.value=d.flash/.18;d.shell.scale.setScalar(c.radius*grow);d.ring.material.opacity=(.45+Math.sin(d.age*3)*.1)*fade;for(const [i,p]of d.puffs.entries()){const u=(i*.618+d.age*.035)%1,y=(.12+.65*((i*.379+d.age*.07)%1))*c.radius,r=Math.sqrt(Math.max(0,c.radius*c.radius-y*y))*(.25+u*.55),a=i*2.399+d.age*.12;p.position.set(Math.cos(a)*r,y,Math.sin(a)*r);p.scale.setScalar(c.radius*(.55+.2*u));p.material.opacity=.38*fade;}}
 update(dt){this.time+=dt;this.cooldown=Math.max(0,this.cooldown-dt);for(const d of [...this.domes]){d.age+=dt;d.flash=Math.max(0,d.flash-dt);if(d.age>=this.config.duration)this.remove(d);else this.animate(d);}}
 remove(d){d.root.removeFromParent();d.material.dispose();d.ring.material.dispose();d.root.traverse(o=>{if(o.isSprite)o.material.dispose();if(o.isMesh&&o.geometry===this.canisterGeometry)o.material.dispose();});this.domes=this.domes.filter(v=>v!==d);}
 diagnostics(){return{active:this.domes.length,cooldown:this.cooldown,deployed:this.deployed,blocked:this.blocked,radius:this.config.radius,duration:this.config.duration,domes:this.domes.map(d=>({center:d.center.toArray(),remaining:this.config.duration-d.age}))};}
}
const guarded=new WeakSet();
export function guardHeroInSmoke(hero,getSmoke){if(!hero||guarded.has(hero))return;guarded.add(hero);const prior=hero.isDamageProtected?.bind(hero);hero.isDamageProtected=()=>!!prior?.()||!!getSmoke()?.protectsHero(hero);if(hero.receiveEyeHit){const original=hero.receiveEyeHit;hero.receiveEyeHit=function(...args){if(this.isDamageProtected()){getSmoke()?.absorb();return false;}return original.apply(this,args);};}}
